final class AdminController
{
    private static PDO $db;
    private static array $user;
    private static function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
    private static function q(string $sql, array $args=[]): array { $s=self::$db->prepare($sql); $s->execute($args); return $s->fetchAll(); }
    private static function one(string $sql,array $args=[]): ?array { $s=self::$db->prepare($sql);$s->execute($args);$r=$s->fetch();return $r?:null; }
    private static function exec(string $sql,array $args=[]): int { $s=self::$db->prepare($sql);$s->execute($args);return $s->rowCount(); }
    private static function audit(string $action,string $type, string|int|null $id, array $meta=[]): void { self::exec('INSERT INTO audit_log(user_id,action,entity_type,entity_id,result,metadata_json,ip_address) VALUES(?,?,?,?,?,?,?)',[self::$user['id']??null,$action,$type,$id===null?null:(string)$id,'success',json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$_SERVER['REMOTE_ADDR']??null]); }
    private static function csrf(): string { return '<input type="hidden" name="_csrf" value="'.self::e(Security::csrf()).'">'; }
    private static function post(): void { if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST') throw new \RuntimeException('Método no permitido.'); Security::verifyCsrf(); }
    private static function go(string $r): never { header('Location: ?r='.rawurlencode($r)); exit; }
    private static function id(): int { return max(0,(int)($_REQUEST['id']??0)); }
    private static function form(string $action,string $fields,string $button='Guardar',string $method='post'): string { $method=strtolower($method)==='get'?'get':'post'; return '<form method="'.$method.'" '.($action==='admin-pharmacy-import'?'enctype="multipart/form-data" ':'').'action="?r='.self::e($action).'">'.($method==='post'?self::csrf():'').$fields.'<button type="submit">'.self::e($button).'</button></form>'; }
    private static function input(string $label,string $name,mixed $value='',string $type='text',string $extra=''): string { return '<label>'.self::e($label).' <input type="'.self::e($type).'" name="'.self::e($name).'" value="'.self::e($value).'" '.$extra.'></label><br>'; }
    private static function table(array $rows): string { if(!$rows)return '<p>Sin resultados.</p>'; $h='<div class="table-wrap"><table class="admin-table"><thead><tr>'; foreach(array_keys($rows[0]) as $k)$h.='<th>'.self::e($k).'</th>'; $h.='</tr></thead><tbody>'; foreach($rows as $r){$h.='<tr>';foreach($r as $k=>$v)$h.='<td>'.($k==='action_html'?(string)$v:self::e($v)).'</td>';  $h.='</tr>';}$h.='</tbody></table></div>';return $h; }
    private static function nav(): string { $links=['admin/dashboard'=>'Inicio','admin/campaigns'=>'Campañas','admin/questions'=>'Preguntas','admin/rules'=>'Reglas','admin/tsi'=>'TSI','admin/pharmacies'=>'Farmacias','admin/users'=>'Usuarios','admin/records'=>'Registros','admin/incidents'=>'Incidencias','admin/stats'=>'Estadísticas','admin/export'=>'Exportar','admin/audit'=>'Auditoría','admin/dictionary'=>'Diccionario'];$s='<nav class="admin-nav">';foreach($links as $r=>$t)$s.='<a href="?r='.$r.'">'.$t.'</a> · ';return $s.'</nav><hr>'; }
    private static function page(string $title,string $body): never { \page($title,$body); }
    private static function campaign(int $id): array { $c=self::one('SELECT * FROM campaigns WHERE id=?',[$id]);if(!$c)throw new \RuntimeException('Campaña no encontrada.');return $c; }
    private static function editable(int $id): array { $c=self::campaign($id);$v=self::one('SELECT * FROM campaign_config_versions WHERE campaign_id=? AND version=?',[$id,$c['config_version']]);if($c['state']!=='preparation'||!$v||$v['state']!=='draft')throw new \RuntimeException('La configuración solo se modifica en preparación y versión draft.');return $c; }
