    public static function dispatch(string $route,array $user): never
    {
        Security::requireRole('admin'); self::$db=Database::connection();self::$user=$user;
        try { $body=match($route) {
            'admin/dashboard'=>self::dashboard(), 'admin/campaigns'=>self::campaigns(), 'admin/campaign-new'=>self::campaignNew(), 'admin/campaign'=>self::campaignView(), 'admin/campaign-save'=>self::campaignSave(), 'admin/campaign-activate'=>self::campaignActivate(), 'admin/campaign-close'=>self::campaignClose(),
            'admin/questions'=>self::questions(), 'admin/question-save'=>self::questionSave(), 'admin/question-delete'=>self::questionDelete(), 'admin/rules'=>self::rules(), 'admin/rules-save'=>self::rulesSave(), 'admin/tsi'=>self::tsi(), 'admin/tsi-save'=>self::tsiSave(),
            'admin/pharmacies'=>self::pharmacies(), 'admin/pharmacy-edit'=>self::pharmacyEdit(), 'admin/pharmacy-save'=>self::pharmacySave(), 'admin/pharmacy-toggle'=>self::pharmacyToggle(), 'admin/pharmacy-import'=>self::pharmacyImport(), 'admin/pharmacy-import-confirm'=>self::pharmacyImportConfirm(), 'admin/users'=>self::users(), 'admin/user-save'=>self::userSave(), 'admin/user-toggle'=>self::userToggle(), 'admin/user-reset'=>self::userReset(),
            'admin/records'=>self::records(), 'admin/record'=>self::record(), 'admin/record-invalidate'=>self::recordInvalidate(), 'admin/incidents'=>self::incidents(), 'admin/incident-resolve'=>self::incidentResolve(), 'admin/stats'=>self::stats(), 'admin/export'=>self::exportForm(), 'admin/export-csv'=>self::exportCsv(), 'admin/audit'=>self::auditPage(), 'admin/dictionary'=>self::dictionary(), default=>'<p>Ruta administrativa desconocida.</p>'};
            self::page('Administración · '.str_replace('admin/','',$route),$body);
        } catch(\PDOException $e) { error_log('[AdminController] database error: '.$e->getMessage()); self::page('Administración · Aviso','<p class="error">No se pudo completar la operación por un problema interno. Consulte con soporte de la campaña.</p><p><a href="?r=admin/dashboard">Volver al inicio</a></p>'); } catch(Throwable $e) { self::page('Administración · Aviso','<p class="error">'.self::e($e->getMessage()).'</p><p><a href="?r=admin/dashboard">Volver al inicio</a></p>'); }
    }
    private static function dashboard(): string { $nums=[];foreach(['campañas'=>'campaigns','registros'=>'patient_records','farmacias'=>'pharmacies','usuarios'=>'users','incidencias abiertas'=>'record_incidents'] as $l=>$t)$nums[]=['Métrica'=>$l,'Total'=>(int)self::one("SELECT COUNT(*) n FROM $t".($t==='record_incidents'?" WHERE status='open'":''))['n']];return '<h1>Panel administrativo</h1>'.self::table($nums).'<h2>Campañas</h2>'.self::table(self::q('SELECT id,name,state,starts_at,ends_at,config_version FROM campaigns ORDER BY id DESC LIMIT 30')); }
    private static function campaigns(): string { return '<h1>Campañas</h1><p><a href="?r=admin-campaign-new">Crear campaña</a></p>'.self::table(self::q('SELECT id,name,state,starts_at,ends_at,config_version FROM campaigns ORDER BY id DESC')); }
    private static function campaignNew(): string { if($_SERVER['REQUEST_METHOD']==='POST'){self::post();$name=trim($_POST['name']??'');if($name==='')throw new \RuntimeException('Nombre requerido.');$qtpl=self::jsonFile('questionnaire.json');$rtpl=self::jsonFile('scoring.example.json');self::$db->beginTransaction();try{$s=self::$db->prepare("INSERT INTO campaigns(name,state,config_version) VALUES(?,'preparation',1)");$s->execute([$name]);$id=(int)self::$db->lastInsertId();self::exec("INSERT INTO campaign_config_versions(campaign_id,version,state,created_by,change_note) VALUES(?,1,'draft',?,'Copiada de plantilla')",[$id,self::$user['id']??null]);foreach($qtpl['questions'] as $i=>$x)self::exec('INSERT INTO questions(campaign_id,config_version,code,prompt,help_text,response_type,required,position,options_json,validation_json,is_builtin) VALUES(?,1,?,?,?,?,?,?,?,?,1)',[$id,$x['code'],$x['prompt'],'',$x['type'],!empty($x['required'])?1:0,$i+1,isset($x['options'])?json_encode($x['options'],JSON_UNESCAPED_UNICODE):null,(isset($x['validation'])?json_encode($x['validation'],JSON_UNESCAPED_UNICODE):(isset($x['options_source'])?json_encode(['options_source'=>$x['options_source']],JSON_UNESCAPED_UNICODE):null))]);foreach(['FINDRISC'=>$rtpl['findrisc'],'MEDAS'=>$rtpl['medas']] as $scale=>$bundle)self::exec("INSERT INTO score_rules(campaign_id,config_version,scale,rule_code,title,rule_json,position) VALUES(?,1,?,'bundle',?,?,?)",[$id,$scale,$scale,json_encode($bundle,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$scale==='FINDRISC'?1:2]);self::audit('campaign.create','campaign',$id);self::$db->commit();self::go('admin/campaign');}catch(Throwable $e){if(self::$db->inTransaction())self::$db->rollBack();throw $e;}}return '<h1>Nueva campaña (usa plantillas instaladas)</h1>'.self::form('admin-campaign-new',self::input('Nombre','name'),'Crear'); }
    private static function campaignView(): string { $id=self::id();$c=self::campaign($id);$html='<h1>'.self::e($c['name']).'</h1>'.self::table([$c]).'<p><a href="?r=admin-questions&amp;campaign='.$id.'">Preguntas</a> · <a href="?r=admin-rules&amp;campaign='.$id.'">Reglas</a></p>';if($c['state']==='preparation'){$html.=self::form('admin-campaign-save',self::input('ID','id',$id,'hidden').self::input('Nombre','name',$c['name']).self::input('Inicio','starts_at',substr((string)$c['starts_at'],0,16),'datetime-local').self::input('Fin','ends_at',substr((string)$c['ends_at'],0,16),'datetime-local'),'Guardar campaña');$html.=self::form('admin-campaign-activate',self::input('ID','id',$id,'hidden').'<p class="warning">Decisiones abiertas: unidad de glucosa; tabaquismo; «Paciente masculino» diabetes gestacional. Tras activar, la configuración queda bloqueada.</p><label><input type="checkbox" name="ack" value="1" required> Confirmo que revisé la configuración clínica y las decisiones abiertas.</label>','Activar campaña');}if($c['state']==='active')$html.=self::form('admin-campaign-close',self::input('ID','id',$id,'hidden'),'Cerrar campaña');return $html; }
    private static function campaignSave(): string { self::post();$id=(int)($_POST['id']??0);$c=self::editable($id);$name=trim($_POST['name']??'');$a=$_POST['starts_at']?:null;$b=$_POST['ends_at']?:null;if($a&&$b&&strtotime($a)>=strtotime($b))throw new \RuntimeException('La fecha de inicio debe ser anterior al fin.');self::exec('UPDATE campaigns SET name=?,starts_at=?,ends_at=? WHERE id=?',[$name,$a?date('Y-m-d H:i:s',strtotime($a)):null,$b?date('Y-m-d H:i:s',strtotime($b)):null,$id]);self::audit('campaign.update','campaign',$id);self::go('admin/campaign'); }
