    private static function validateBundle(array $f,array $m): void
    {
        $rangeKeys=['age','bmi','waist_male','waist_female'];
        $maxes=[];
        foreach($rangeKeys as $key){
            $bands=$f[$key]??null;
            if(!is_array($bands)||!$bands)throw new \RuntimeException('Faltan bandas FINDRISC: '.$key.'.');
