                if($i===array_key_last($bands)&&$max!==null)throw new \RuntimeException('La última banda de '.$key.' debe terminar sin límite superior.');
                if($i<array_key_last($bands)&&$max===null)throw new \RuntimeException('Solo la última banda de '.$key.' puede no tener máximo.');
                if($min!==null&&$max!==null&&(float)$min>(float)$max)throw new \RuntimeException('Intervalo invertido en '.$key.'.');
                if($i>0){$prev=$bands[$i-1];$prevMax=$prev['max']??null;if($prevMax===null||$min===null||(float)$prevMax!==(float)$min)throw new \RuntimeException('Hay hueco o solapamiento entre bandas de '.$key.'.');$prevInc=(bool)($prev['max_inclusive']??false);$currInc=(bool)($band['min_inclusive']??true);if($prevInc===$currInc)throw new \RuntimeException($prevInc?'Las bandas se solapan en '.$key.'.':'Hay un valor sin banda en '.$key.'.');}
            }
            $maxes[$key]=max(array_map(static fn($b)=>(int)$b['score'],$bands));
        }
        $mapKeys=['physical_activity','fruit_vegetables','antihypertensive','high_glucose','family_history'];
        foreach($mapKeys as $key){$map=$f[$key]??null;if(!is_array($map)||!$map)throw new \RuntimeException('Falta el mapa FINDRISC '.$key.'.');foreach($map as $score)if(!is_int($score)||$score<0)throw new \RuntimeException('Cada puntuación de '.$key.' debe ser entero no negativo.');$maxes[$key]=max($map);}
        $findriscMax=$maxes['age']+$maxes['bmi']+max($maxes['waist_male'],$maxes['waist_female'])+$maxes['physical_activity']+$maxes['fruit_vegetables']+$maxes['antihypertensive']+$maxes['high_glucose']+$maxes['family_history'];
        foreach([['bands'=>$f['interpretation']??null,'expected'=>$findriscMax,'label'=>'Interpretación FINDRISC'],['bands'=>$m['interpretation']??null,'expected'=>14,'label'=>'Interpretación MEDAS']] as $spec){$bands=$spec['bands'];$name=$spec['label'];if(!is_array($bands)||!$bands)throw new \RuntimeException('Falta '.$name.'.');$previousMax=null;foreach($bands as $i=>$band){$min=$band['min']??null;$max=$band['max']??null;$label=trim((string)($band['label']??''));if(!is_numeric($min)||(float)$min!==(float)(int)$min||$label==='')throw new \RuntimeException($name.' requiere mínimos enteros y etiquetas.');$min=(int)$min;if($min<0)throw new \RuntimeException($name.' no admite mínimos negativos.');if($i===0&&$min!==0)throw new \RuntimeException($name.' debe comenzar en 0.');if($i>0&&($previousMax===null||$min!==$previousMax+1))throw new \RuntimeException($name.' contiene un hueco o solapamiento entre categorías.');if($max!==null){if(!is_numeric($max)||(float)$max!==(float)(int)$max||(int)$max<$min)throw new \RuntimeException($name.' contiene un máximo inválido.');$max=(int)$max;}if($i<array_key_last($bands)&&$max===null)throw new \RuntimeException('Solo la última categoría de '.$name.' puede quedar abierta.');$previousMax=$max;}if($previousMax!==null&&$previousMax<(int)$spec['expected'])throw new \RuntimeException($name.' no cubre el total máximo posible ('.$spec['expected'].').');}
        if(!isset($m['items'])||count($m['items'])!==14)throw new \RuntimeException('MEDAS requiere exactamente 14 reglas.');
