    }
    private static function validateRuleMaps(array $f,array $questions): void
    {
        $qmap=$questions;if(array_is_list($questions)){$qmap=[];foreach($questions as $row)if(isset($row['code']))$qmap[$row['code']]=$row;}
        $mapQuestions=['physical_activity'=>'actividad_fisica','fruit_vegetables'=>'fruta_verdura_diaria','antihypertensive'=>'hipertension_medicacion','high_glucose'=>'hiperglucemia_previa','family_history'=>'antecedentes_familiares'];
        foreach($mapQuestions as $key=>$code){$options=json_decode((string)($qmap[$code]['options_json']??''),true);if(!is_array($options)||!is_array($f[$key]??null)||array_diff_key($options,$f[$key])||array_diff_key($f[$key],$options))throw new \RuntimeException('Las reglas de '.$key.' deben cubrir exactamente las opciones vigentes de '.$code.'.');}
    }
    private static function scoringHarness(array $qs,array $f,array $m): array
    {
        $service=new \App\Services\ScoringService();$qmap=[];foreach($qs as $q)$qmap[$q['code']]=$q;$pick=static function(array $bands): float {foreach($bands as $b){$lo=$b['min']??null;$hi=$b['max']??null;$v=$lo===null?($hi===null?0:(float)$hi-1):($hi===null?(float)$lo+1:((float)$lo+(float)$hi)/2);if(($lo===null||(($b['min_inclusive']??true)?$v>=$lo:$v>$lo))&&($hi===null||(($b['max_inclusive']??false)?$v<=$hi:$v<$hi)))return $v;}throw new \RuntimeException('Harness: regla sin valor de prueba cubierto.');};$choice=static function(string $code)use($qmap): string {$opts=json_decode((string)($qmap[$code]['options_json']??''),true);if(!is_array($opts)||!$opts)throw new \RuntimeException('Harness: opciones faltantes para '.$code);return (string)array_key_first($opts);};
        $a=['diabetes_actual'=>'no','edad'=>(string)$pick($f['age']??[]),'peso_kg'=>'70','altura_m'=>'1'];$bmi=$pick($f['bmi']??[]);$a['peso_kg']=(string)sqrt(max(0.01,$bmi));$a['cintura_cm']=(string)$pick($f['waist_male']??[]);$a['sexo']='hombre';foreach(['actividad_fisica'=>'physical_activity','fruta_verdura_diaria'=>'fruit_vegetables','hipertension_medicacion'=>'antihypertensive','hiperglucemia_previa'=>'high_glucose','antecedentes_familiares'=>'family_history'] as $answer=>$rule)$a[$answer]=$choice(['actividad_fisica'=>'actividad_fisica','fruta_verdura_diaria'=>'fruta_verdura_diaria','hipertension_medicacion'=>'hipertension_medicacion','hiperglucemia_previa'=>'hiperglucemia_previa','antecedentes_familiares'=>'antecedentes_familiares'][$answer]);$fr=$service->calculateFindrisc($a,$f);if(($fr['status']??null)!=='calculated'||!is_int($fr['total']??null)||trim((string)($fr['interpretation']??''))==='')throw new \RuntimeException('Harness: FINDRISC no produjo total/interpretación válidos.');$na=$service->calculateFindrisc(['diabetes_actual'=>'si'],$f);if(($na['status']??null)!=='not_applicable')throw new \RuntimeException('Harness: diabetes actual no resultó not_applicable.');$ma=[];foreach(range(1,14) as $i){$code=sprintf('medas_%02d',$i);$ma[$code]=(string)($m['items'][$code]['qualifying_answer']??$choice($code));}$mr=$service->calculateMedas($ma,$m);if(($mr['status']??null)!=='calculated'||count($mr['items']??[])!==14||!is_int($mr['total']??null)||$mr['total']<0||$mr['total']>14||trim((string)($mr['interpretation']??''))==='')throw new \RuntimeException('Harness: MEDAS no produjo 14 ítems y total/interpretación válidos.');return ['findrisc'=>'calculated','findrisc_total'=>$fr['total'],'findrisc_interpretation_valid'=>true,'diabetes_actual'=>'not_applicable','medas'=>'calculated','medas_items'=>count($mr['items']),'medas_total'=>$mr['total'],'medas_interpretation_valid'=>true];
    }
