    private static function pharmacyImport(): string
    {
        self::post();
        if (!isset($_FILES['csv']) || ($_FILES['csv']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) throw new \RuntimeException('Seleccione un CSV válido.');
        if (($_FILES['csv']['size'] ?? 0) > 2097152) throw new \RuntimeException('El CSV supera el límite de 2 MiB.');
        $raw=file_get_contents($_FILES['csv']['tmp_name']); if ($raw===false || preg_match('//u',$raw)!==1) throw new \RuntimeException('El archivo debe estar codificado en UTF-8.');
        $f=fopen('php://temp','r+'); fwrite($f,$raw); rewind($f); $head=fgetcsv($f);
        if ($head!==['soe','name','locality','tax_id','email']) { fclose($f); throw new \RuntimeException('La cabecera exacta debe ser: soe,name,locality,tax_id,email. No se admiten columnas sobrantes.'); }
        $preview=[];$seen=[];$line=1;
        while (($row=fgetcsv($f))!==false) { $line++; if(count($preview)>=1000) { fclose($f); throw new \RuntimeException('El CSV supera el máximo de 1000 filas de datos.'); }
            $errors=[]; if(count($row)!==5) { $errors[]='Número de columnas incorrecto (se esperan exactamente 5).'; $row=array_slice(array_pad($row,5,''),0,5); }
            $r=array_combine(['soe','name','locality','tax_id','email'],array_map(fn($v)=>trim((string)$v),$row));
            if(!preg_match('/^OR-\d{3}-F$/',$r['soe']))$errors[]='SOE inválido (formato OR-###-F).';
            foreach(['name'=>'Nombre','locality'=>'Localidad','tax_id'=>'NIF/CIF'] as $key=>$label)if($r[$key]==='')$errors[]="$label obligatorio.";
            if(!filter_var($r['email'],FILTER_VALIDATE_EMAIL))$errors[]='Correo inválido.';
            $dups=[];if($r['soe']!==''){if(isset($seen[$r['soe']]))$dups[]='Duplicado dentro del archivo (fila '.$seen[$r['soe']].').';else $seen[$r['soe']]=$line;
                if(self::one('SELECT id FROM pharmacies WHERE soe=?',[$r['soe']]))$dups[]='SOE ya existe en la base de datos.';}
            $preview[]=['row'=>$line,'data'=>$r,'errors'=>$errors,'duplicates'=>$dups,'result'=>($errors||$dups)?'No válido':'Listo'];
        } fclose($f);
        if(session_status()!==PHP_SESSION_ACTIVE)session_start();
        $token=bin2hex(random_bytes(24)); $_SESSION['pharmacy_import_preview']=['admin_id'=>(string)(self::$user['id']??''),'token'=>$token,'rows'=>$preview,'created'=>time()];
        $ok=count(array_filter($preview,fn($r)=>!$r['errors']&&!$r['duplicates']));$bad=count($preview)-$ok;
        $view=[];foreach($preview as $r)$view[]=['Fila'=>$r['row'],'SOE'=>$r['data']['soe'],'Resultado'=>$r['result'],'Errores'=>implode(' ',$r['errors']),'Duplicados'=>implode(' ',$r['duplicates'])];
        $confirm=($bad===0&&$ok>0)?self::form('admin-pharmacy-import-confirm','<input type="hidden" name="preview_token" value="'.self::e($token).'">','Confirmar importación'): '<p>No se puede confirmar: hay errores o duplicados (o no hay filas de datos).</p>';
        return '<h1>Previsualización de farmacias</h1><p>Filas: '.count($preview).'; listas: '.$ok.'; con errores/duplicados: '.$bad.'. Las nuevas farmacias se crearán deshabilitadas.</p>'.self::table($view).$confirm;
    }
    private static function pharmacyImportConfirm(): string
    {
        self::post(); if(session_status()!==PHP_SESSION_ACTIVE)session_start(); $p=$_SESSION['pharmacy_import_preview']??null;
        if(!is_array($p))throw new \RuntimeException('La previsualización de sesión expiró; vuelva a subir el CSV.');
        $token=(string)($_POST['preview_token']??'');if(!hash_equals((string)$p['token'],$token)||(string)$p['admin_id']!==(string)(self::$user['id']??''))throw new \RuntimeException('Previsualización inválida o perteneciente a otro administrador; vuelva a subir el CSV.');
        if(time()-(int)$p['created']>1800){unset($_SESSION['pharmacy_import_preview']);throw new \RuntimeException('La previsualización expiró; vuelva a subir el CSV.');}
        foreach($p['rows'] as $r)if($r['errors']||$r['duplicates'])throw new \RuntimeException('La previsualización contiene errores o duplicados; vuelva a subir el CSV corregido.');
        self::$db->beginTransaction();try{foreach($p['rows'] as $r){$d=$r['data'];if(self::one('SELECT id FROM pharmacies WHERE soe=? FOR UPDATE',[$d['soe']]))throw new \RuntimeException('Un SOE fue creado tras la previsualización; vuelva a subir el CSV.');self::exec('INSERT INTO pharmacies(soe,name,locality,tax_id,email,enabled) VALUES(?,?,?,?,?,0)',[$d['soe'],$d['name'],$d['locality'],$d['tax_id'],$d['email']]);}self::audit('pharmacy.import','pharmacy',null,['inserted'=>count($p['rows'])]);self::$db->commit();unset($_SESSION['pharmacy_import_preview']);}catch(Throwable $e){if(self::$db->inTransaction())self::$db->rollBack();throw $e;}
        return '<h1>Importación confirmada</h1><p>Farmacias añadidas: '.count($p['rows']).'. Todas están deshabilitadas.</p>';
    }
