    private static function exportCsv(): string { self::post();$cid=(int)($_POST['campaign_id']??0);$c=self::campaign($cid);$ver=(int)$c['config_version'];$qs=self::q('SELECT code FROM questions WHERE campaign_id=? AND config_version=? ORDER BY position',[$cid,$ver]);$cols=['soe','patient_code','composite_id','revision_number','record_status','created_at','FINDRISC_score','FINDRISC_interpretation','MEDAS_score','MEDAS_interpretation'];foreach($qs as $q)$cols[]='v'.$ver.'_'.$q['code'];$sql='SELECT r.id,r.patient_code,r.revision_number,r.record_status,r.created_at,p.soe FROM patient_records r JOIN pharmacies p ON p.id=r.pharmacy_id WHERE r.campaign_id=? AND r.config_version=? AND r.record_status=\'valid\'';$args=[$cid,$ver];if(!empty($_POST['pharmacy_id'])){$sql.=' AND r.pharmacy_id=?';$args[]=(int)$_POST['pharmacy_id'];}$rows=self::q($sql.' ORDER BY p.soe,r.patient_code',$args);self::audit('data.export','campaign',$cid,['pharmacy_id'=>$_POST['pharmacy_id']??null,'count'=>count($rows)]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="campaign-'.$cid.'-records.csv"');$o=fopen('php://output','wb');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,$cols);foreach($rows as $r){$v=$r['soe'].'-'.$r['patient_code'];$d=array_fill_keys($cols,'');$d['soe']=$r['soe'];$d['patient_code']=$r['patient_code'];$d['composite_id']=$v;$d['revision_number']=$r['revision_number'];$d['record_status']=$r['record_status'];$d['created_at']=$r['created_at'];foreach(self::q('SELECT scale,total_score,interpretation FROM record_calculations WHERE record_id=? AND is_current=1',[$r['id']]) as $x){$d[$x['scale'].'_score']=$x['total_score'];$d[$x['scale'].'_interpretation']=$x['interpretation'];}foreach(self::q('SELECT question_code,answer_value FROM record_answers WHERE record_id=?',[$r['id']]) as $a){$key='v'.$ver.'_'.$a['question_code'];if(isset($d[$key]))$d[$key]=$a['answer_value'];}fputcsv($o,array_map(function($k)use($d){$v=(string)$d[$k];return preg_match('/